// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/simulator/SimulatorBase.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/core/MonetrixConfig.sol";

contract AuditAgentPoC is SimulatorBase {
    // ATTACK TIMELINE:
    // 1. [Setup] SimulatorBase deploys the full protocol. The vault holds spot hedge tokens 
    //    (e.g., BTC/ETH) on HyperCore L1 as collateral in a portfolio margin perp account.
    // 2. [T=0] The 0x80F accountValueSigned precompile returns the aggregate margin value, 
    //    which ALREADY includes the mark-to-market value of these spot positions.
    // 3. [T=1] MonetrixAccountant._readL1Backing() adds this perp account value, AND THEN 
    //    iterates config.tradeableAssets() to add the spot balances again via 0x801.
    // 4. [T=2] We record the inflated totalBackingSigned() and surplus().
    // 5. [T=3] Governor removes the double-counted asset from tradeableAssets to reveal the 
    //    true backing (simulating a fix or exposing the discrepancy).
    // 6. [T=4] totalBackingSigned() drops significantly, proving the spot tokens were counted twice.
    // 7. [Assert] Verify backingBefore > backingAfter, confirming the accounting logic error 
    //    that allows excess yield declaration and sUSDM dilution.

    function test_exploit() public {
        // Step 1 & 2: Read the inflated backing and surplus
        int256 backingBefore = accountant.totalBackingSigned();
        int256 surplusBefore = accountant.surplus();

        console.log("Step 2: Inflated totalBackingSigned =", uint256(backingBefore));
        console.log("Step 2: Inflated surplus =", uint256(surplusBefore));

        // Step 3: Identify the double-counted asset from tradeableAssets
        // The vulnerability occurs because tradeableAssets contains spot tokens 
        // whose value is already embedded in the perp accountValueSigned.
        uint256 assetCount = config.tradeableAssetsLength();
        require(assetCount > 0, "No tradeable assets configured");

        (uint32 perpIndex, uint32 spotIndex, uint32 spotPairAssetId) = accountant.tradeableAssets(0);
        console.log("Step 3: Double-counted perpIndex =", perpIndex);
        console.log("Step 3: Double-counted spotIndex =", spotIndex);

        // Step 4: Remove the asset from tradeableAssets to stop the second counting pass
        // This exposes the true economic backing by preventing _readSpotAssetUsdc from 
        // adding the spot balance a second time.
        vm.prank(governor);
        config.removeTradeableAsset(perpIndex);

        // Step 5: Read the corrected (true) backing
        int256 backingAfter = accountant.totalBackingSigned();
        int256 surplusAfter = accountant.surplus();

        console.log("Step 5: True totalBackingSigned =", uint256(backingAfter));
        console.log("Step 5: True surplus =", uint256(surplusAfter));

        // Step 6: Assert the double-counting vulnerability
        // The backing and surplus must be strictly greater before the fix, 
        // proving that spot hedge tokens were counted twice in the original state.
        assertGt(
            backingBefore, 
            backingAfter, 
            "totalBackingSigned was inflated by double-counting spot hedge tokens"
        );

        assertGt(
            surplusBefore, 
            surplusAfter, 
            "surplus was inflated, allowing excess yield declaration and sUSDM dilution"
        );

        // Additional proof: The drop in backing should be material (greater than zero)
        int256 phantomBacking = backingBefore - backingAfter;
        assertGt(
            phantomBacking, 
            0, 
            "Phantom backing from double-counted spot tokens must be material"
        );

        console.log("Step 6: Phantom backing amount =", uint256(phantomBacking));
    }
}
